/* Portable review controller. Mock state is never production authorization. */
const M=VynvoriMock,storageKey='vynvori-design111-v1';
let model=M.initial(),message='',error='',dialogOpener=null,comparison=null;
const params=new URLSearchParams(location.search),scenario=params.get('scenario');
try{const stored=sessionStorage.getItem(storageKey);if(stored){const raw=JSON.parse(stored);M.validateModel(raw);model=raw;}if(scenario){const fixtureKey='scenario:'+scenario+':reset:'+(params.get('reset')||'none');if(sessionStorage.getItem('phase6e-active-fixture')!==fixtureKey){model=M.fixture(scenario);sessionStorage.setItem('phase6e-active-fixture',fixtureKey);}}}catch{model=M.initial();error='Invalid stored review fixture rejected. A clean private draft was restored.';}
const e=escapeHTML,mb=(label,action,extra='',secondary=false)=>`<button class="btn ${secondary?'secondary':''}" data-m="${action}" ${extra}>${label}</button>`,link=(label,path,cls='btn secondary')=>`<a class="${cls}" href="#${path}">${label}<span aria-hidden="true">↗</span></a>`;
const field=(label,id,value='',type='text',help='')=>`<div class="field"><label for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}" data-field="${id}">${e(value)}</textarea>`:`<input id="${id}" data-field="${id}" type="${type}" value="${e(value)}">`}${help?`<p class="field-help">${help}</p>`:''}</div>`;
const check=(label,id)=>`<label class="check"><input type="checkbox" id="${id}">${label}</label>`;
const artView=(url,alt='Original illustrative house study')=>`<img src="${e(url)}" alt="${e(alt)}">`;
const stamp=()=>`<p class="artifact-stamp">Internal review simulation. Synthetic credits, rights, capability and quote terms exercise behavior only. No actual offers, provider calls, identity verification or production qualification.</p>`;
function save(){try{if(model.stage>=4)model.projectStage=model.stage;M.validateModel(model);sessionStorage.setItem(storageKey,JSON.stringify(model));}catch(x){error=x.message;}}
function announce(text){$('#status').textContent=text;clearTimeout(announce.timer);announce.timer=setTimeout(()=>{$('#status').textContent='';},6000);}
function openDialog(title,html){dialogOpener=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog').showModal();$('#dialog').querySelector('button')?.focus();}
$('#dialog').addEventListener('close',()=>dialogOpener?.isConnected?dialogOpener.focus():main.focus());
function routePath(){return location.hash.slice(1)||'/';}
function go(path){if(location.hash==='#'+path)render(true);else location.hash=path;}
function stage(n){model.stage=n;save();go(M.screen(model).route);}
function persistRender(text){save();render();if(text)announce(text);}
function statusHTML(){return `${error?`<p class="error" role="alert" id="form-error">${e(error)}</p>`:''}${message?`<p class="notice" role="status">${e(message)}</p>`:''}`;}
function walletHTML(){const w=model.wallet;return `<dl class="wallet"><div><dt>Available credits</dt><dd>${w.availableUnits}</dd></div><div><dt>Reserved credits</dt><dd>${w.reservedUnits}</dd></div><div><dt>Held for review</dt><dd>${w.heldForReviewUnits}</dd></div></dl>`;}
function financeHTML(){const f=M.financials(model);return `<section class="financial"><h2>Package credit record</h2><p class="small muted">Customer package amounts / synthetic fixture</p><dl><dt>Authorized maximum</dt><dd>${f.maximumAuthorizedHoldUnits}</dd><dt>Currently reserved</dt><dd>${f.currentlyReservedUnits}</dd><dt>Held for reconciliation</dt><dd>${f.currentlyHeldForReviewUnits}</dd><dt>Settled to date</dt><dd>${f.cumulativelySettledUnits}</dd><dt>Released to date</dt><dd>${f.cumulativelyReleasedUnits}</dd></dl><p class="small">${e(f.packageId)}<br>Quote ${e(f.quoteId)}</p><p class="small muted">Current balances and cumulative transactions are separate; do not add them as a balance.</p></section>`;}
function casesHTML(){return model.cases.map(c=>`<section class="notice"><p class="mini-label">${e(c.kind.replaceAll('_',' '))} / ${e(c.state)}</p><p>${e(c.publicMessage)}</p><p class="small">Case ${e(c.caseId)}</p></section>`).join('');}
const titles=['A COLLECTION OF ONE.','FIND YOUR CREATIVE LANGUAGE.','DESCRIBE YOUR WORLD.','YOUR BRIEF, IN FOCUS.','THREE WAYS INTO YOUR WORLD.','ONE IDEA. THREE DIRECTIONS.','A FIRST LOOK, IF YOU WANT IT.','YOUR SEPARATE PREVIEW.','THREE ORIGINAL POSSIBILITIES.','YOUR DIRECTIONS, TAKING FORM.','YOUR WORK IS STILL HERE.','FIND YOUR COMPOSITION.','REFINE THE FIRST DETAILS.','ONE MORE CONSIDERED CHANGE.','GIVE THIS VERSION ITS FINAL FORM.','YOUR ARTWORK REMAINS YOURS.','A FINAL VERSION. YOUR NEXT CHOICE.','THE STORY OF YOUR WORK.'];
function studioHead(history=false){const s=M.screen(history?{...model,stage:17}:model);return `<div class="atelier-head"><p class="mini-label">THE CREATIVE ATELIER / ${s.screenId}</p><div>${link('Project history','/studio/projects/project-atelier-01/history','link')}</div></div><div class="step-strip" role="group" aria-label="Creative journey">${['BRIEF','DIRECTIONS','CONCEPTS','REFINE & FINAL'].map((t,i)=>`<span class="${(model.stage<4?0:model.stage<8?1:model.stage<12?2:3)===i?'active':''}">${String(i+1).padStart(2,'0')} / ${t}</span>`).join('')}</div>`;}
function studio(){M.screen(model);if(model.stage===0)return entry();if(model.stage===1||model.stage===2)return briefForm();if(model.stage===3)return briefReview();let content='',rail='';
switch(model.stage){
case 4:content=`<div class="art-frame">${artView('assets/arch-study.svg','Architectural reference, planning illustration only')}</div><p class="notice">The Creative Director builds a bounded plan from your brief. Planning is nonbillable; paid concepts have not begun.</p><div class="actions">${mb('Review the three directions','director')}</div>`;rail=`<h2>A considered beginning.</h2><p>${e(M.normalizedBrief(model).prompt)}</p><p>One bounded planning round in this simulation. No image generation or credit debit.</p>`;break;
case 5:content=`<div class="direction-list">${M.directions.map((d,i)=>`<article class="direction">${artView(M.artFiles[i],d.visualIntent)}<div><span class="mini-label">DIRECTION 0${i+1} / ${e(d.directionId)}</span><h2>${e(d.title)}</h2><p>${e(d.rationale)}</p><p class="muted">${e(d.visualIntent)}</p></div></article>`).join('')}</div><div class="actions">${mb('Approve all three directions','approve')}${mb('Return to the brief','edit-brief','',true)}</div>`;rail=`<h2>Approve a whole plan.</h2><p>These are direction boards using fixed local house studies, not paid concept results. Approving freezes all three direction IDs and plan revision together.</p><p class="small">Planning costs 0 customer credits. Three new concepts require separate consent.</p>`;break;
case 6:content=`<div class="art-frame">${artView(M.artFiles[model.promoDirection])}</div><p class="notice">One optional preview for an eligible verified identity. Zero customer credits. Separate from all three paid package outputs.</p><div class="field"><label for="promo-direction">Choose exactly one approved direction</label><select id="promo-direction">${M.directions.map((d,i)=>`<option value="${i}" ${model.promoDirection===i?'selected':''}>${e(d.title)}</option>`).join('')}</select></div>${check('I understand this promotional preview is additional, may be preview-only and is not print-qualified.','promo-consent')}<div class="actions">${mb('Start separate preview','promo',model.promo!=='eligible'?'disabled':'')}${mb('Skip preview / inspect package','bundle-quote','',true)}</div>`;rail=`<h2>${model.promo==='eligible'?'An optional first look.':'Preview unavailable.'}</h2><p>Promotion status: ${e(model.promo)}.</p><p>One identity-bound promotional result, from one selected direction. It is not a credit discount or a purchased package slot.</p><p>Sign-in here is explicitly simulated.</p>`;break;
case 7:content=model.promo==='delivered'?`<div class="art-frame">${artView(M.artFiles[model.promoDirection].replace('-study.svg','-promo.svg'))}</div><p class="notice">Separate promotional version promo-v1 saved. Paid bundle delivery remains 0/3.</p>`:`<div class="art-frame"><div><p class="mini-label">PROMOTIONAL PREVIEW</p><h2>${model.promo==='unknown'?'Outcome under review.':model.promo==='running'?'Preview in progress.':model.promo==='failed'?'Preview did not deliver.':'Promotion unavailable.'}</h2><p>${model.promo==='unknown'?'Claim remains held. No second preview attempt.':model.promo==='used'?'This verified identity has already used its promotional offer.':'No package concept is consumed.'}</p></div></div>`;content+=`<div class="actions">${model.promo==='running'?mb('Check saved preview','promo-delivery'):''}${mb('Inspect the three-concept package','bundle-quote','',true)}${model.promo==='unknown'?mb('Open a recovery case','support','',true):''}</div>`;rail=`<h2>One additional result.</h2><p>${e(M.directions[model.promoDirection].title)}</p><p>Customer credits: 0.</p><p>Not necessarily final, licensed for export or print-qualified.</p><p class="small">Operation operation-promo-01</p>`;break;
case 8:return quoteView(false);
case 9:case 10:case 11:return concepts();
case 12:case 13:return refinement();
case 14:return quoteView(true);
case 15:content=`<p class="notice warning">Standard final rendering is unavailable in this fixture. No new final charge or hold can start. Existing concepts and entitlements remain preserved.</p><div class="compare-pair">${model.history.filter(h=>h.kind==='concept').slice(0,2).map(h=>`<figure>${artView(h.previewUrl,h.label)}<figcaption>${e(h.versionId)} / illustrative preview, not print-qualified</figcaption></figure>`).join('')}</div>${casesHTML()}<div class="actions">${mb('Open in editor for preview','open-editor')}${mb('Ask for a resolution','support','',true)}${link('Inspect saved versions','/studio/projects/project-atelier-01/history')}</div>`;rail=`<h2>Qualification is separate.</h2><p>Capability: unavailable / revoked / rights-limited in this scenario.</p><p>Service-caused expiry is suspended after route loss. A support case can offer a consented equivalent or approved remedy, without a surprise surcharge.</p>`;break;
case 16:return finalView();
case 17:return historyView();
}
return `<section class="atelier">${studioHead()}<h1 class="atelier-title">${titles[model.stage]}</h1>${statusHTML()}<div class="workspace"><div>${content}</div><aside class="work-rail">${rail}${walletHTML()}${casesHTML()}${stamp()}</aside></div></section>${note()}`;}
function entry(){return `<section class="atelier"><div class="studio-entry"><div><p class="eyebrow">THE CREATIVE ATELIER / IDEA TO WEAR</p><h1 class="atelier-title">A COLLECTION<br>OF ONE.</h1><p class="readable">Start with a point of view. Shape an original world. Give it form on a garment, or keep it as art.</p><div class="path-options"><a class="path-card" href="#/studio/guide"><span class="mini-label">01 / GUIDED</span><h2>Guide Me ↗</h2><p>A visual brief, one considered choice at a time.</p></a><a class="path-card" href="#/studio/free"><span class="mini-label">02 / FREEFORM</span><h2>Create Freely ↗</h2><p>Your words. Your references. An open beginning.</p></a></div><div class="rule">${link('Upload Your Design','/customize','link')}<p class="small muted">Your own artwork. Independent garment editing. No AI credits.</p></div>${stamp()}</div><div class="entry-art">${artView(M.artFiles[0])}<p class="mini-label">HOUSE STUDY / OPEN STRUCTURE</p></div></div></section>${note()}`;}
const wizardFields=[['niche','Niche / theme',['Architecture after dark','Botanical abstraction','Original gaming worlds','Personal symbolism']],['aesthetic','Aesthetic',['Sculptural minimalism','Raw expression','Graphic surrealism','Quiet geometry']],['palette','Palette',['Ivory / mineral','Warm earth / ink','Restrained chromatic','Monochrome']],['motifs','Motifs',['Open arches','Broken orbits','Organic fragments','Precise typography']],['exactPhrase','Optional exact phrase',[]],['references','Reference inspiration',[]],['restrictions','Restrictions and rights acknowledgement',[]]];
function briefForm(){const free=model.stage===2,b=model.brief,[key,label,choices]=wizardFields[model.wizard];let fields=free?field('Describe original artwork','prompt',b.prompt,'textarea','No provider receives this prompt. Draft saved locally in this tab.')+field('Optional exact phrase','exactPhrase',b.exactPhrase)+field('Restrictions / what to avoid','restrictions',b.restrictions,'textarea'):key==='references'?`<div class="field"><label for="reference-input">Choose private inspiration</label><input id="reference-input" type="file" accept="image/png,image/jpeg,image/webp" multiple><p class="field-help">Local filenames only in the normalized brief; do not use copyrighted references without permission.</p>${b.references.map(s=>`<p class="small">${e(s)}</p>`).join('')}</div>`:field(label,key,b[key]||'',key==='restrictions'?'textarea':'text');
if(choices.length)fields+=`<div class="choices" aria-label="${e(label)} choices">${choices.map((c,i)=>`<button data-m="brief-choice" data-key="${key}" data-value="${e(c)}" aria-pressed="${b[key]===c}">${key==='palette'?`<span class="mood-swatch" aria-hidden="true" style="background:${['#e8e6df','#79776e','#c8c6bd','#11110f'][i]}"></span>`:''}${e(c)}</button>`).join('')}</div>`;
if(free||model.wizard===6)fields+=`<label class="check"><input id="rightsAcknowledged" type="checkbox" ${b.rightsAcknowledged?'checked':''}>I own or have permission for supplied text and references. Creation, export, gallery and printing have separate rights checks.</label>`;
return `<section class="atelier">${studioHead()}<div class="workspace"><div class="readable"><p class="mini-label">${free?'PROMPT FIRST':`${model.wizard+1} / 7 · VISUAL BRIEF`}</p><h1 class="atelier-title">${free?'DESCRIBE<br>YOUR WORLD.':e(label).toUpperCase()+'.'}</h1>${!free?`<div class="wizard-progress" role="group" aria-label="Step ${model.wizard+1} of 7">${wizardFields.map((_,i)=>`<span class="${i<=model.wizard?'current':''}"></span>`).join('')}</div>`:''}${statusHTML()}${fields}${free?`<div class="field"><label for="reference-input">Reference inspiration (optional)</label><input id="reference-input" type="file" accept="image/png,image/jpeg,image/webp" multiple><p class="field-help">${b.references.map(e).join(', ')||'Choose only references you have permission to use.'}</p></div>`:''}<div class="actions">${!free&&model.wizard>0?mb('Back','wizard-back','',true):''}${mb(free||model.wizard===6?'Review your brief':'Next','brief-next')}</div>${link(free?'Switch to Guide Me':'Switch to Create Freely',free?'/studio/guide':'/studio/free','link')}</div><aside class="work-rail"><div class="art-frame">${artView(M.artFiles[model.wizard%3])}</div><p class="small muted">Original house-study inspiration. The Director will create three differentiated directions after you review and claim your brief.</p><p class="small">Compatible fields stay with you when switching modes. A guest can draft for free.</p>${stamp()}</aside></div></section>${note()}`;}
function briefReview(){const b=M.normalizedBrief(model);return `<section class="atelier">${studioHead()}<h1 class="atelier-title">YOUR BRIEF,<br>IN FOCUS.</h1><div class="workspace"><div>${statusHTML()}<dl class="brief-summary">${[['Theme',b.niche||b.prompt],['Aesthetic',b.aesthetic||'From prompt'],['Palette',b.palette||'Director interpretation'],['Motifs',b.motifs||'From prompt'],['Exact text',b.exactPhrase||'None'],['References',b.references.join(', ')||'None'],['Restrictions',b.restrictions||'Original work; no third-party copying'],['Rights acknowledged',b.rightsAcknowledged?'Yes':'No']].map(([k,v])=>`<dt>${k}</dt><dd>${e(v)}</dd>`).join('')}</dl><p class="notice">Identity boundary / ${e(model.claim)}. Simulated sign-in uses no real SSO endpoint, token, credential or email linking.</p><div class="actions">${['expired','conflict'].includes(model.claim)?mb('Recover a private draft copy','recover-draft'):mb('Simulate sign-in & claim draft','claim')}${mb('Edit brief','edit-brief','',true)}</div></div><aside class="work-rail"><h2>Your idea stays private.</h2><p>Authenticated planning and promotional or paid creation require verified identity in production. LuckyLittleDevil integration is unaudited; this demonstration does not emulate its actual sessions.</p><p>A claim conflict never transfers someone else’s work. Expiration recovery creates a new private draft copy.</p>${stamp()}</aside></div></section>${note()}`;}
function quoteView(final){const q=M.quote(model,final?'final':'bundle'),reasons=M.guards(model,final?'final':'bundle',true);const source=model.history.find(h=>h.versionId===model.selected);return `<section class="atelier">${studioHead()}<div class="workspace"><div><p class="mini-label">${final?'SEPARATE FINAL GENERATION':'THE THREE-CONCEPT PACKAGE / 3 + 2'}</p><h1 class="atelier-title">${final?'ONE VERSION.<br>ITS FINAL FORM.':'THREE ORIGINAL<br>POSSIBILITIES.'}</h1>${statusHTML()}${q?`<p class="quote-price">${q.creditsQuoted} <small>synthetic test credits</small></p><p class="small muted">SYNTHETIC FIXTURE / not VYNVORI pricing, denomination, validity or published commercial terms.<br>${e(q.quoteVersionId)} · fixed test clock ${M.clock}<br>Fixture expires ${e(q.expiresAt)} / ${e(model.quoteState)}</p>`:`<p class="notice warning">No authorizable offer exists: ${e(reasons.join(' · '))}. You may inspect the package content; no paid concept-only purchase is allowed.</p>`}${final&&source?`<p>Source ${e(source.versionId)} / ${e(source.label)}</p><div class="art-frame">${artView(source.previewUrl)}</div>`:''}<div class="quote-grid"><section><h2>${final?'Standard final':'Included'}</h2><ul>${final?'<li>One separately quoted Standard final from this owned source version.</li><li>Illustrative qualification only; physical print approval remains separate.</li>':'<li>Three new concepts: one per approved direction.</li><li>Up to two optional included guided refinements.</li><li>Refinements stay with this project and source branch.</li>'}</ul></section><section><h2>Purchased separately</h2><ul><li>${final?'Any additional revision requires a fresh quote.':'Qualified final generation is separately quoted.'}</li><li>Digital export, garment, printing and shipping excluded.</li><li>No EU delivery promise or real shipping quote.</li></ul></section></div><section class="rule"><h2>Available next uses</h2><p>Standard final: ${model.standard?'qualified in synthetic fixture':'unavailable'}.</p><p>Licensed digital artwork export: ${model.digital&&model.region!=='EU'?'eligible in fixture / separately purchased':'blocked / preview only'}.</p><p>Garment route: ${model.garment&&model.region!=='EU'?'eligible in fixture / separately purchased':'blocked / supplier and shipping unapproved'}.</p><p class="small muted">Region ${model.region}. Separate creation, commercial export, showcase and physical-production permissions. Premium ${model.premium?'qualified in selected mock capability; separate Premium quote NOT_IMPLEMENTED':'unavailable; no independent qualification'}.</p></section><p class="notice">Partial saved concepts remain viewable; fewer than three deliveries block normal selection/final progression. Unknown outcomes preserve holds and open recovery cases without a new charge.</p><p class="notice">${final?'Successful persisted final delivery may close unused included refinements under these disclosed synthetic terms. Quote or submission alone does not close them; unknown outcomes keep closure pending.':'Skipped refinements can be restored while eligible. Included operations have no additional customer credit debit. An optional promotion is a separate result, never one of the three paid concepts.'}</p>${walletHTML()}${check(final?'I authorize this separate synthetic final quote and understand closure upon verified delivery, independent settlement and quality-case review.':'I authorize exactly three NEW concepts and up to two optional included refinements. I understand the separate final charge, exclusions, downstream restrictions and partial-delivery/reconciliation terms.','quote-consent')}<div class="actions">${mb(final?'Authorize separate final simulation':'Authorize package simulation',final?'authorize-final':'authorize',reasons.length||!q?'disabled':'')}${mb('Inspect a fresh quote','requote','',true)}${mb('Simulate wallet top-up','topup','',true)}</div><p class="small">Top-up never resumes authorization. Inspect a fresh quote and provide fresh explicit consent.</p></div><aside class="work-rail"><h2>Your credit position.</h2>${walletHTML()}${reasons.length?`<p class="notice warning">${e(reasons.join(' · '))}</p>`:''}${!final?`<p class="small">Approved plan ${e(model.planHash||'not approved')}</p>${M.directions.map(d=>`<p class="small">${e(d.title)} / ${e(d.directionId)}</p>`).join('')}`:financeHTML()}${stamp()}</aside></div></section>${note()}`;}
function concepts(){const cs=M.cards(model),n=M.count(model);return `<section class="atelier">${studioHead()}<h1 class="atelier-title">${n===3?'FIND YOUR<br>COMPOSITION.':'YOUR WORK IS<br>TAKING FORM.'}</h1><p>${n}/3 concepts persisted. ${n<3?'Saved partial artwork is available to inspect; regular selection remains on hold.':'Three distinct direction-linked versions are saved. Customer settlement is independently recorded.'}</p>${statusHTML()}<div class="workspace"><div><div class="concept-list">${cs.map(c=>`<article class="concept-card ${c.isSelected?'selected':''}">${c.safePreviewUrl?artView(c.safePreviewUrl,c.accessibleDescription):`<div class="concept-placeholder" role="status">${c.status==='under_review'?'Outcome uncertain / held for reconciliation':c.status==='artifact_persisting'?'Artifact persistence pending':c.status==='verified_uncharged_failure'?'Failed / verified uncharged':'Provider result pending'}</div>`}<h2>${e(c.directionTitle)}</h2><p>${e(c.directionId)}<br>${e(c.versionId||'No persisted version')}</p><p>${e(c.status.replaceAll('_',' '))}</p>${c.versionId?mb(n===3?'Select this concept':'Inspect saved partial','concept-select',`data-version="${c.versionId}"`):''}${c.operation?`<div class="receipt">Customer operation receipt<br>${e(c.operation.operationId)}<br>${e(c.operation.receipt.receiptId||'Not authorized')} / ${e(c.operation.receipt.kind.replaceAll('_',' '))}<br>${c.operation.receipt.kind==='settled'?`Settled ${c.operation.receipt.settledUnits} credits`:c.operation.receipt.kind==='released'?`Released ${c.operation.receipt.releasedUnits} credits`:`Held ${c.operation.receipt.heldUnits||0} credits`}</div>`:''}</article>`).join('')}</div><div class="actions">${model.slots.some(s=>s==='running'||s==='artifact_persisting')?mb('Check saved results','observe'):''}${mb('Open a recovery case','support','',true)}${link('View immutable history','/studio/projects/project-atelier-01/history')}</div>${casesHTML()}<p class="small muted">This simulation reveals deterministic fixture results only after an explicit check. A refresh resumes the same operation IDs and never starts new generation.</p></div><aside class="work-rail">${financeHTML()}${walletHTML()}${stamp()}</aside></div></section>${note()}`;}
function refinement(){const i=model.stage-12,s=model.refinements[i],source=model.history.find(h=>h.versionId===model.selected),used=s.state==='used',after=used?model.history.find(h=>h.versionId===s.deliveredVersionId):null;return `<section class="atelier">${studioHead()}<h1 class="atelier-title">A CONSIDERED<br>CHANGE / 0${i+1}.</h1><div class="workspace"><div>${statusHTML()}<p>Included refinement ${i+1} of 2 / 0 additional customer credits.<br>Slot ${e(s.state)} · source ${e(s.sourceVersionId||model.selected)}.</p><div class="compare-pair"><figure>${artView((used?model.history.find(h=>h.versionId===s.sourceVersionId):source)?.previewUrl||M.artFiles[0])}<figcaption>Before / ${e(used?s.sourceVersionId:model.selected)}</figcaption></figure><figure>${artView(after?.previewUrl||source?.previewUrl||M.artFiles[0])}<figcaption>${used?'After / '+e(s.deliveredVersionId):'Current source / no new delivery yet'}</figcaption></figure></div>${field('What to change','change',model.change,'textarea')}${field('What to preserve','preserve',model.preserve,'textarea')}${field('Exact typography (optional)','exactTypography',model.exactTypography)}<p class="small muted">Fixed local comparison artwork demonstrates lineage. Text controls record exact intent; no AI responds to the request.</p><div class="actions">${s.state==='available'?mb('Generate included refinement','refine'):s.state==='skipped'?mb('Restore included slot','restore'):s.state==='pending'?mb('Check saved refinement','refinement-delivery'):''}${['available','skipped'].includes(s.state)?mb('Skip for now','skip','',true):''}${mb(i===0?'Continue to refinement 2':'Inspect separate final quote',i===0?'next-refinement':'final-quote','',true)}</div>${['pending','unknown'].includes(s.state)?'<p class="notice warning">This included operation is locked. No duplicate execution or additional debit. Unknown outcomes require reconciliation.</p>':''}</div><aside class="work-rail"><h2>Two optional changes.</h2>${model.refinements.map(r=>`<p>Slot ${r.ordinal}: ${e(r.state)}<br><span class="small">${e(r.sourceVersionId||'Source not chosen')}</span></p>`).join('')}<p>Skipping is reversible while the package is open. A pending/unknown operation stays locked. Successful final delivery may close unused slots after prior disclosure.</p>${link('Inspect branch history','/studio/projects/project-atelier-01/history','link')}${walletHTML()}${stamp()}</aside></div></section>${note()}`;}
function finalView(){const o=M.finalOperation(model),finalId=`final-v${model.finalSequence}`,h=model.history.find(x=>x.versionId===finalId);return `<section class="atelier">${studioHead()}<h1 class="atelier-title">${h?'A FINAL VERSION.<br>YOUR NEXT CHOICE.':'YOUR FINAL,<br>IN PROGRESS.'}</h1><div class="workspace"><div>${statusHTML()}<p>Frozen source ${e(model.finalSource)} / operation ${e(o.operationId)}</p>${h?`<div class="art-frame">${artView(h.previewUrl)}</div><p class="notice">Final version persisted / ${e(finalId)}. This illustrative artwork is not a supplier-approved print master.</p><div class="actions">${mb('Use this version','use')}${mb('Save without using','save','',true)}${mb('Request another revision (new quote)','new-final','',true)}${mb('Report a quality problem','quality-dialog','',true)}</div><p class="small">Choice: ${model.useVersion?'using '+e(model.useVersion):model.saved.includes(finalId)?'saved privately':'no use preference yet'}. Your choice cannot settle, reverse or approve a charge.</p>`:`<div class="art-frame"><div><p class="mini-label">${e(model.final.replaceAll('_',' '))}</p><h2>${model.final==='unknown'?'Outcome under review.':'Reserved. Then created. Then saved.'}</h2><p>${model.final==='unknown'?'The original operation remains held. No blind retry and no silent closure of unused refinements.':'Credits and artwork progress are independently confirmed.'}</p></div></div><div class="actions">${model.final==='reserved'?mb('Check operation status','final-running'):model.final==='running'?mb('Check saved final','final-delivery'):''}${mb('Ask for a resolution','support','',true)}</div>`}<div class="actions">${link('History & next steps','/studio/projects/project-atelier-01/history')}</div>${casesHTML()}</div><aside class="work-rail"><h2>Separate customer receipt.</h2><p>${e(o.receipt.receiptId)}<br>${e(o.receipt.kind.replaceAll('_',' '))}</p><p>${o.receipt.kind==='settled'?'Settled '+o.receipt.settledUnits:'Held '+o.receipt.heldUnits} synthetic credits.</p><p>Persistence ${h?'confirmed in fixture':'unconfirmed'} · settlement ${model.finalSettlement} · quality ${model.cases.some(c=>c.kind==='quality_issue')?'under review':'not reported'}.</p>${model.finalArchive.length?`<p>Prior final receipts retained: ${model.finalArchive.map(a=>e(a.versionId)+' / '+e(a.settlement)).join('<br>')}</p>`:''}<p>Unused included slots: ${model.refinements.map(s=>s.state).join(' / ')}.</p>${walletHTML()}${stamp()}</aside></div></section>${note()}`;}
function historyView(){return `<section class="atelier">${studioHead(true)}<h1 class="atelier-title">THE STORY<br>OF YOUR WORK.</h1><div class="workspace"><div>${statusHTML()}<section class="notice"><p class="mini-label">CREATIVE BRIEF → APPROVED DIRECTIONS</p><p>${e(M.normalizedBrief(model).prompt)}</p><p class="small">${e(model.planHash||'Plan not approved')} / ${M.directions.map(d=>e(d.title)).join(' · ')}</p></section><ol class="history-list">${model.history.map(h=>`<li>${artView(h.previewUrl||M.artFiles[0],h.label)}<div><p class="mini-label">${e(h.kind)} / ${e(h.versionId)}</p><h2>${e(h.label)}</h2><p>Parent ${e(h.parentVersionId||'approved direction / separate promo')}<br>${e(h.rightsSummary)}</p>${mb('Inspect version','inspect-version',`data-version="${h.versionId}"`,true)}</div></li>`).join('')}</ol>${!model.history.length?'<p>No persisted artwork yet. History does not start generation.</p>':''}<div class="actions">${mb('Open in Garment Editor','open-editor',model.history.length?'':'disabled')}${mb('Save privately','save-history','',true)}${mb('Review eligible digital export','export-dialog',!model.digital||!model.history.length?'disabled':'',true)}${link('Gallery consent & moderation','/gallery')}</div>${casesHTML()}</div><aside class="work-rail"><h2>${model.final==='delivered'?'A version, preserved.':'Work in progress.'}</h2><p>Immutable versions retain source branches and direction identities. Promotional previews never count toward the purchased three concepts.</p><p>Saved private by default. Gallery requires separate explicit consent and moderation. Export and garment use obey separate rights/capability states.</p>${link('Resume project','/studio/projects/project-atelier-01','link')}${walletHTML()}${stamp()}</aside></div></section>${note()}`;}
function sceneCanvas(scene=model.scene){return `<div class="garment-canvas ${scene.side==='back'?'back':''}" aria-label="${scene.side} illustrative garment mockup"><div class="mm-zone" role="group" aria-label="Illustrative 200 by 260 mm zone">${scene[scene.side].filter(l=>l.visible).map(l=>`<button class="scene-layer" data-layer="${l.id}" data-m="select-layer" aria-pressed="${scene.selected===l.id}" aria-label="${e(l.kind==='text'?l.text:l.id)}. Arrow keys move in millimeters." style="left:${l.xMm/2}%;top:${l.yMm/2.6}%;width:${l.widthMm/2}%;height:${l.heightMm/2.6}%;transform:rotate(${l.rotation}deg)">${l.kind==='image'?artView(l.source,'Local original artwork layer'): `<span>${e(l.text)}</span>`}</button>`).join('')}</div></div>`;}
function editorView(review=false){const s=model.scene,l=s[s.side].find(x=>x.id===s.selected),issues=M.sceneIssues(s);try{M.editorProjection(model);}catch(x){error='Draft validation: '+x.message;}if(review)return compositionReview();return `<section class="atelier"><div class="atelier-head"><p class="mini-label">THE GARMENT EDITOR / ${s.versions.length?'ED-02':'ED-01'} / ${e(s.provenance)}</p>${link(s.provenance==='byo'?'Return to storefront':'Return to your project',s.provenance==='byo'?'/':'/studio/projects/project-atelier-01','link')}</div><h1 class="atelier-title">GIVE YOUR<br>IDEA FORM.</h1>${statusHTML()}<p class="small">Free guest composition / no AI credits. Draft is local to this browser tab; no real upload or durable account save.</p><div class="tools">${['front','back'].map(side=>`<button data-m="side" data-side="${side}" aria-pressed="${s.side===side}">${side[0].toUpperCase()+side.slice(1)}</button>`).join('')}${mb('Undo','undo',s.undo.length?'':'disabled',true)}${mb('Redo','redo',s.redo.length?'':'disabled',true)}</div><div class="canvas-tabs" role="group" aria-label="Editor panel"><button data-m="panel" data-panel="canvas" aria-pressed="${s.panel==='canvas'}">Canvas</button><button data-m="panel" data-panel="controls" aria-pressed="${s.panel==='controls'}">Controls</button></div><div class="editor-stage ${s.panel}"><div class="editor-canvas">${sceneCanvas()}<p class="editor-status">Illustrative garment mockup / not a print master.<br>Demonstration zone 200 × 260 mm. Supplier-unapproved example geometry.</p><p class="small muted">Drag an unlocked layer, use arrow keys (Shift = 5 mm) or edit numeric controls. Front and back keep independent scenes.</p></div><aside class="scene-controls"><h2>Your layers.</h2><div class="tools">${mb('Add house image','add-image','',true)}${mb('Add exact text','add-text','',true)}</div><div class="field"><label for="local-upload">Upload your own design</label><input id="local-upload" type="file" accept="image/png,image/jpeg,image/webp"><p class="field-help">PNG/JPEG/WebP, max 8 MB. Private local preview. Original bytes retained for owner retrieval.</p></div><div class="layer-list" role="group" aria-label="Layers, uppermost last">${s[s.side].map((x,i)=>`<button data-m="select-layer" data-layer="${x.id}" aria-pressed="${s.selected===x.id}">${i+1} / ${e(x.kind==='text'?x.text.slice(0,40):x.id)} · ${x.visible?'visible':'hidden'} ${x.locked?'/ locked':''}</button>`).join('')}</div>${l?`<div class="tools">${[['up','Raise'],['down','Lower'],['visible',l.visible?'Hide':'Show'],['lock',l.locked?'Unlock':'Lock'],['remove','Remove']].map(([a,t])=>`<button data-m="${a}" ${l.locked&&['up','down','remove'].includes(a)?'disabled':''}>${t}</button>`).join('')}</div>${l.kind==='text'?field('Exact text / Archivo OFL','layer-text',l.text):l.source.startsWith('data:')?mb('Retrieve unchanged original','original-download','',true):''}<div class="numeric-grid">${[['xMm','X / mm'],['yMm','Y / mm'],['widthMm','Width / mm'],['heightMm','Height / mm'],['rotation','Rotate / degrees']].map(([k,label])=>field(label,'layer-'+k,l[k],'number')).join('')}</div>${mb('Apply layer controls','apply-layer',l.locked?'disabled':'',true)}`:'<p>Select a layer to adjust its geometry.</p>'}</aside></div><section class="editor-status"><p>${issues.length?issues.map(e).join('<br>'):'No bounds/resolution issues under this illustrative profile.'}</p><p>Real supplier print dimensions, resolution/color policy and qualification remain blocked.</p></section><div class="actions">${mb('Save local draft','save-scene','',true)}${mb('Freeze & review composition','freeze',issues.length?'disabled':'')}</div><p class="small">Scene revision ${s.revision} / ${s.versions.length} immutable saved mock versions. Original artwork → composed preview → garment mockup; print artifact absent.</p></section>${note()}`;}
function compositionReview(){const v=M.selectedSnapshot(model),projection=M.reviewProjection(model),s=v?{...model.scene,front:v.front,back:v.back}:model.scene,issues=v?M.sceneIssues(s):['Freeze a composition first.'];return `<section class="atelier"><p class="mini-label">ED-03 / COMPOSITION REVIEW</p><h1 class="atelier-title">A COMPOSITION.<br>A CLEAR PROOF.</h1>${statusHTML()}<div class="workspace"><div>${v?`<div class="frozen-proof garment-canvas ${model.scene.side==='back'?'back':''}" data-version="${v.identity.compositionVersionId}" data-hash="${v.identity.sceneHashSha256}"><img src="${M.proofFor(model,model.scene.side)}" alt="Frozen ${model.scene.side} proof ${e(v.identity.compositionVersionId)}"></div>`:''}<div class="tools">${['front','back'].map(side=>mb(side+' frozen proof','side',`data-side="${side}"`,true)).join('')}</div><p class="caption">Illustrative garment mockup. Frozen scene ${e(v?.identity.compositionVersionId||'not frozen')} / no print master exists.</p><div class="actions">${link('Edit a new version','/customize/composition-01')}${mb('Add frozen simulation to cart','add-frozen',!v||issues.length||!projection.cartQuote?'disabled':'')}</div></div><aside class="work-rail"><h2>Print eligibility pending.</h2><p>${projection.newUnfrozenEditsExist?'New draft edits exist. This review still shows the prior frozen proof. Freeze again for a new quote.':'Proof and quote refer to this exact frozen version.'}</p><p class="small">Proof ${e(projection.displayedProof?.artifactId||'pending')} · quote ${e(projection.cartQuote?.quoteId||'not requested')}</p>${mb('Obtain simulated composition quote','composition-quote','',true)}${mb('Review composed artwork export','composition-export','',true)}<p>Originals are separate from this composed preview and garment photograph. None is a DTF manufacturing master.</p><p class="notice warning">Supplier profile unapproved. Human QA required after authoritative payment. Checkout unavailable.</p>${issues.map(x=>`<p class="error">${e(x)}</p>`).join('')}<div class="field"><label for="composition-size">Demo garment size</label><select id="composition-size">${['S','M','L','XL','XXL'].map(x=>`<option ${x!==v?.identity.variantId.split('-').at(-1)?'disabled':''}>${x}</option>`).join('')}</select></div><p class="small">One illustrative base zone; extra-zone prices await verified Medusa configuration. No garment price, shipping estimate or legal merchant is fabricated.</p><p class="small">Material edits require a new frozen version, re-quote and customer proof consent.</p>${stamp()}</aside></div></section>${note()}`;}
function cartView(){return `<section class="atelier"><p class="mini-label">CO-01 / MEDUSA COMMERCE SIMULATION</p><h1 class="atelier-title">THE BAG.</h1>${statusHTML()}${model.cart.length?model.cart.map((c,i)=>`<article class="account-card"><h2>Your personalized garment.</h2><p>Frozen scene ${e(c.versionId)} / size ${e(c.size)} / ${e(c.region)}</p><p>Quote ${e(c.quote)}. Garment price, taxes, duties and shipping unconfirmed.</p><p class="small">Front ${c.front.length} layers / back ${c.back.length} layers. This snapshot stays unchanged when the editor is revised.</p><div class="actions">${mb('Remove','cart-remove',`data-index="${i}"`,true)}${mb('Inspect personalization quote','cart-quote',`data-index="${i}"`,true)}</div></article>`).join(''):'<p>Your demo cart is empty. Compose or discover a garment to begin.</p>'}<div class="readable"><label for="region">Delivery region</label><select id="region">${['US','AU','EU'].map(x=>`<option ${model.region===x?'selected':''}>${x}</option>`).join('')}</select><p class="notice warning">${model.region==='EU'?'EU service is not promised.':'US direct / AU consolidation remain gated pending real rates, duties and delivery evidence.'} Checkout unavailable. No payment or order is placed here.</p>${mb('Checkout unavailable','checkout','disabled')}<p class="small">A simulated paid custom order would still remain on human pre-print QA hold. Wallet credits do not define garment pricing.</p></div><div class="actions">${link('Continue discovering','/collections/gaming')}${link('Upload Your Design','/customize')}</div></section>${note()}`;}
function accountView(path){const section=path.split('/')[2]||'projects';return `<section class="atelier"><p class="mini-label">AC-01 / SIMULATED OWNER ACCOUNT</p><h1 class="atelier-title">YOUR PRIVATE<br>COLLECTION.</h1><nav class="account-nav" aria-label="Account">${['projects','credits','orders','exports','gallery','settings'].map(v=>link(v[0].toUpperCase()+v.slice(1),'/account/'+v,'link')).join('')}</nav>${statusHTML()}<p class="notice">${model.identity==='simulated'?'Simulated identity issuer urn:review:vynvori / subject fixture-owner-01. No actual account session exists.':'Guest view: simulated sign-in required to inspect owner-only account fixtures.'}</p>${model.identity!=='simulated'?mb('Simulate sign-in for review','account-signin'):section==='credits'?`${walletHTML()}${financeHTML()}${casesHTML()}<p>Receipts relate to customer authorizations. No provider expenditure appears in this statement.</p>`:section==='orders'?`<section class="account-card"><h2>Illustrative order / QA hold.</h2><p>No actual order or purchase exists. Review fixture: captured payment projection, frozen composition and awaiting_human_qa.</p><p>Payment and manufacturing release are separately guarded.</p>${link('Inspect simulated order','/account/orders/order-fixture-01','link')}</section>`:section==='exports'?`<section class="account-card"><h2>Digital entitlements.</h2><p>${model.digital?'Licensed export available only in this synthetic rights state.':'Rights limited / digital purchase unavailable.'}</p><p>Export ${model.exportState}. Artwork export and composition export are distinct; unchanged uploaded originals are free to their owner.</p><div class="actions">${mb('Inspect eligible artwork export','export-dialog',!model.digital?'disabled':'')}${model.exportState==='entitled'?mb('Retrieve illustrative export','download-export','',true):''}${model.exportState==='expired'?mb('Renew simulated download access','renew-export','',true):''}</div></section>`:section==='gallery'?`<p>Publication ${model.gallery}. Private by default; separate consent and moderation.</p>${link('Manage gallery permission','/gallery')}`:section==='settings'?'<p>Identity, logout and account deletion integrations are BLOCKED pending LuckyLittleDevil source audit. No credential form is introduced.</p>':`<section class="account-card"><h2>Atelier / 01</h2><p>${model.history.length} saved versions · ${M.count(model)}/3 concepts · private</p><div class="actions">${link('Resume your project','/studio/projects/project-atelier-01')}${link('Version history','/studio/projects/project-atelier-01/history')}</div></section><section class="account-card"><h2>Your garment draft.</h2><p>${model.scene.versions.length} local frozen versions. Guest-to-owner claim is simulated.</p>${link('Open garment composition','/customize/composition-01')}</section>`}${casesHTML()}${stamp()}</section>${note()}`;}
function galleryView(){const own=model.history.at(-1),published=model.gallery==='published';return `<section class="atelier"><p class="mini-label">GA-01 / SHOWCASE ONLY</p><h1 class="atelier-title">EXPRESSION,<br>IN COMPANY.</h1>${statusHTML()}<div class="gallery-layout"><div>${published&&own?`${artView(own.previewUrl,'Sanitized illustrative gallery derivative')}<h2>Atelier / 01</h2><p>House study / simulated owner. Moderated sanitized showcase derivative only.</p><div class="actions">${mb(model.galleryLiked?'Liked / undo':'Like this showcase','gallery-like',`aria-pressed="${model.galleryLiked}"`,true)}${mb('Copy showcase review link','gallery-share','',true)}${mb('Report a concern','gallery-report','',true)}</div>`:`<div class="art-frame">${artView(M.artFiles[1])}</div><h2>The house studies.</h2><p>Illustrative editorial study. Your private originals are not displayed as community submissions.</p>`}<p class="small muted">No purchases, remixing or downloads of another creator’s original artwork in MVP.</p></div><aside class="work-rail"><h2>Your publication choice.</h2><p>Current permission: ${e(model.gallery)}.</p><p>${model.gallery==='pending'?'Submitted for moderation. No public post yet.':model.gallery==='rejected'?'Moderation rejected this fixture. Your private version remains available.':model.gallery==='revoked'?'Showcase permission revoked. Original work stays private.':'Projects begin privately. Showcase consent does not grant merchandise or remix rights.'}</p>${['private','rejected','revoked'].includes(model.gallery)?`${check('I explicitly consent to a sanitized showcase derivative of my owned artwork, subject to moderation.','gallery-consent')}${mb('Submit for moderated showcase','publish',!own?'disabled':'')}`:mb('Unpublish / revoke showcase consent','unpublish','',true)}${stamp()}</aside></div></section>${note()}`;}
function qaView(){return `<section class="atelier"><div class="qa-banner">AD-01 / STAFF-ONLY ILLUSTRATIVE QA · This separate review fixture is not a real Admin route or customer authorization.</div><h1 class="atelier-title">BEFORE<br>IT IS PRINTED.</h1>${statusHTML()}<div class="workspace"><div>${sceneCanvas()}<p class="caption">Garment mockup, not manufacturing output.</p><p class="notice">Simulated Medusa captured-payment projection. Payment alone never authorizes print.</p><dl class="brief-summary"><dt>Frozen composition</dt><dd>composition-v4 / synthetic hash scene-fixture-04</dd><dt>Proof artifact</dt><dd>qa-proof-fixture-01 / exact immutable mock reference</dd><dt>Print master</dt><dd>${model.qaPrerequisites?'Synthetic checked-master reference / no real binary':'Absent / supplier-unapproved'}</dd><dt>Supplier profile</dt><dd>${model.qaPrerequisites?'Synthetic approved profile / fixture only':'Unapproved; release blocked'}</dd><dt>Human decision</dt><dd>${e(model.qa)}</dd></dl><div class="actions">${mb('Record illustrative human approval','qa-approve',!model.qaPrerequisites||model.qa!=='awaiting_human_qa'?'disabled':'')}${mb('Release simulated job','qa-release',!model.qaPrerequisites||model.qa!=='approved_for_print'?'disabled':'')}${mb('Require new customer proof approval','material-edit','',true)}</div></div><aside class="work-rail"><h2>A human handoff.</h2><p>Verify paid order, rights, approved supplier profile and exact proof/master/composition hashes before human approval. Revalidate each guard before release.</p><p>Material edits invalidate prior approval and require a new proof and explicit customer reapproval. Customer artwork choice cannot grant staff authority.</p><p>No partner request or real manufacturing release occurs.</p>${stamp()}</aside></div></section>${note()}`;}
function appHeader(path){const dark=path.startsWith('/studio')&&model.stage>=1;$('#header').innerHTML=`<div class="nav"><a class="brand" href="#/" aria-label="VYNVORI home / OBJECTS OF EXPRESSION"><img src="assets/vynvori-symbol-black.svg" alt=""><span>OBJECTS OF EXPRESSION</span></a><nav aria-label="Primary"><a href="#/collections/gaming">Shop</a><a href="#/studio">AI Studio</a><a href="#/customize">Customize</a><a href="#/gallery">Gallery</a></nav><button class="mobile-menu" data-m="menu">Menu</button><a class="account-link" href="#/account/projects">Account</a><a class="baglink" href="#/cart">Bag (${model.cart.length+S.bag.length})</a></div>`;document.body.classList.toggle('studio',dark);document.documentElement.dataset.theme=dark?'studio':path.startsWith('/customize')?'editor':'storefront';}
const legacyRoutes={home:'/',collection:'/collections/gaming',create:'/studio',prompt:'/studio/free',results:'/studio/projects/project-atelier-01',editor:'/customize','garment-review':'/customize/composition-01/review',bag:'/cart',handoff:'/checkout',gallery:'/gallery'};
function remap(html){return html.replace(/href="#([^\"]+)"/g,(all,v)=>`href="#${legacyRoutes[v]|| (v.startsWith('product/')?'/products/'+v.split('/')[1]:v)}"`);}
let lastPath='';
function render(focus=false){const path=routePath();if(path==='/studio')model.stage=0;if(path==='/studio/guide'){model.stage=1;model.brief.entryMode='guided';}if(path==='/studio/free'){model.stage=2;model.brief.entryMode='free';}if(path.startsWith('/studio/brief/'))model.stage=3;
let html;if(path==='/')html=home();else if(path.startsWith('/collections'))html=collection();else if(path.startsWith('/products/')){S.product=path.split('/')[2]==='black-oversized-tshirt'?'rupture':path.split('/')[2];html=product();}else if(path.startsWith('/studio/projects/')){if(model.projectStage!==null)model.stage=model.projectStage;if(path.endsWith('/history')){html=historyView();}else{if(model.stage<4)model.stage=model.identity==='guest'?3:4;html=studio();}}else if(path.startsWith('/studio'))html=studio();else if(path.startsWith('/customize'))html=editorView(path.endsWith('/review'));else if(path==='/cart'||path==='/checkout')html=cartView();else if(path.startsWith('/account/'))html=accountView(path);else if(path.startsWith('/gallery'))html=galleryView();else if(path.startsWith('/admin/vynvori/'))html=qaView();else html=`<section class="atelier"><h1>Review route unavailable.</h1>${link('Return home','/')}</section>`;
appHeader(path);const active=document.activeElement,focusKey=active?.dataset?.m,focusId=active?.id;main.innerHTML=remap(html);document.title='VYNVORI / '+(path==='/'?'Monumental Atelier':path.split('/')[1]);if(focus||lastPath!==path){main.focus({preventScroll:true});window.scrollTo(0,0);}else if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusKey)document.querySelector(`[data-m="${focusKey}"]`)?.focus({preventScroll:true});lastPath=path;save();}
function run(action,payload={}){const r=M.command(model,action,{...payload,expectedRevision:model.revision,...(action==='approve'?{expectedBriefRevision:model.brief.revision}:{})});error=r.ok?'':r.message;message=r.ok?'': '';const targetRoute=r.ok?M.screen(model).route:null;if(r.ok)save();render();announce(r.message);if(r.ok&&['claim','director','approve','promo','authorize','select','authorize-final'].includes(action)){go(targetRoute);main.focus({preventScroll:true});}}
document.addEventListener('input',ev=>{const t=ev.target,id=t.id;if(['niche','aesthetic','palette','motifs','exactPhrase','prompt','restrictions'].includes(id)){model.brief[id]=t.value;model.brief.revision++;save();}if(['change','preserve','exactTypography'].includes(id)){model[id]=t.value;save();}});
document.addEventListener('change',async ev=>{const t=ev.target;if(t.id==='rightsAcknowledged'){model.brief.rightsAcknowledged=t.checked;save();}if(t.id==='promo-direction'){model.promoDirection=Number(t.value);save();}if(t.id==='reference-input'){model.brief.references=[...t.files].map(f=>f.name);save();}if(t.id==='region'){model.region=t.value;model.quoteState='stale';persistRender('Region changed; existing quote must be revalidated.');}if(t.id==='sort'){S.sort=t.value;render();}if(t.id==='local-upload'){const f=t.files[0];if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024)throw Error('Choose a PNG, JPEG or WebP under 8 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});const image=new Image();image.src=data;await image.decode();M.sceneEdit(model,'add-image',{source:data,pixelWidth:image.naturalWidth});model.scene.panel='controls';error='';persistRender('Original image stored in your local tab only. No upload occurred.');}catch(x){error=x.message||'Image decode failed.';render();}}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-m],[data-action]');if(!b||b.disabled)return;if(b.dataset.action)return legacyClick(ev,b);const a=b.dataset.m;error='';message='';
try{switch(a){
case 'menu':openDialog('Explore VYNVORI',`<nav class="dialog-links">${[['Home','/'],['Shop','/collections/gaming'],['AI Studio','/studio'],['Upload Your Design','/customize'],['Gallery','/gallery'],['Account','/account/projects'],['Bag','/cart']].map(([l,p])=>link(l,p,'link')).join('')}</nav>`);break;
case 'brief-choice':model.brief[b.dataset.key]=b.dataset.value;model.brief.revision++;persistRender('Choice saved in your brief.');break;
case 'wizard-back':model.wizard=Math.max(0,model.wizard-1);persistRender();main.focus();break;
case 'brief-next':if(model.stage===1&&model.wizard<6){const k=wizardFields[model.wizard][0];if(model.wizard<4&&!model.brief[k].trim()){error='Choose or enter '+wizardFields[model.wizard][1].toLowerCase()+'.';render();document.getElementById(k)?.focus();break;}model.wizard++;persistRender();main.focus();}else{const errors=M.briefErrors(model);if(errors.length){error=errors.join(' ');render();$('#prompt')?.focus();}else{model.brief=M.normalizedBrief(model);stage(3);}}break;
case 'edit-brief':if(model.authorized){message='Purchased directions are frozen. Start a separate project for a new plan.';render();break;}model.planApproved=false;model.planHash=null;go(model.brief.entryMode==='guided'?'/studio/guide':'/studio/free');break;
case 'claim':case 'recover-draft':case 'director':case 'approve':case 'promo-delivery':case 'topup':case 'requote':case 'observe':case 'skip':case 'restore':case 'refine':case 'refinement-delivery':case 'final-running':case 'final-delivery':case 'use':case 'save':case 'support':case 'unpublish':case 'qa-approve':case 'qa-release':case 'material-edit':run(a);break;
case 'promo':run('promo',{consent:$('#promo-consent').checked});break;
case 'bundle-quote':stage(8);break;
case 'authorize':case 'authorize-final':run(a,{consent:$('#quote-consent').checked});break;
case 'concept-select':if(M.count(model)===3)run('select',{version:b.dataset.version});else openDialog('Saved partial artwork',artView(model.history.find(h=>h.versionId===b.dataset.version)?.previewUrl)+`<p>${e(b.dataset.version)} / partial delivery. Selection is on hold until 3/3 or approved remedy.</p>`);break;
case 'next-refinement':stage(13);break;
case 'final-quote':if(model.refinements.some(s=>['pending','unknown'].includes(s.state))){error='Resolve the included operation before authorizing a final.';render();}else{M.command(model,'requote');stage(model.standard?14:15);}break;
case 'quality-dialog':openDialog('Report a quality problem',`${field('Describe an objective defect','quality-description','','textarea')}<p>Remedy review does not automatically reverse customer charges.</p>${mb('Submit quality report','submit-quality')}`);break;
case 'submit-quality':{const description=$('#quality-description').value;const r=M.command(model,'quality',{description});if(r.ok){$('#dialog').close();persistRender('Quality case opened. No automatic refund.');}else announce(r.message);break;}
case 'new-final':run('new-final');go(M.screen(model).route);break;
case 'inspect-version':model.correction.inspectedVersion=b.dataset.version;save();{const h=model.history.find(x=>x.versionId===b.dataset.version);openDialog(h.label,artView(h.previewUrl)+`<p>${e(h.versionId)} · parent ${e(h.parentVersionId||'direction')} · ${e(h.rightsSummary)}</p>`);break;}
case 'open-editor':{const source=model.history.find(h=>h.versionId===(model.correction.activeVersion||model.useVersion||model.selected))||model.history.at(-1);model.correction.activeVersion=source?.versionId||null;if(!source){announce('No persisted owned version to compose.');break;}model.scene.provenance='studio';M.sceneEdit(model,'add-image',{source:source.previewUrl});save();go('/customize/composition-01');break;}
case 'use-inspected':model.correction.activeVersion=model.correction.inspectedVersion;$('#dialog').close();persistRender('Selected the inspected immutable version for editor and export.');break;
case 'save-history':model.saved=[...new Set([...model.saved,...model.history.map(h=>h.versionId)])];persistRender('All versions retained privately in this tab.');break;
case 'export-dialog':model.correction.activeVersion=model.correction.activeVersion||model.useVersion||model.selected||model.history.at(-1)?.versionId;save();openDialog('Eligible digital artwork export',`<p>Exact artwork version ${e(model.correction.activeVersion)} / separate licensed artwork export / synthetic TEST currency amount 5 units. Garment and composed-art export excluded. No real sale or payment.</p>${check('I consent to the separate illustrative export terms.','export-consent')}${mb('Simulate export entitlement','export-authorize')}`);break;
case 'export-authorize':{const r=M.command(model,'export',{consent:$('#export-consent').checked,version:model.correction.activeVersion});if(r.ok){$('#dialog').close();persistRender('Synthetic entitlement created; no payment.');}else announce(r.message);break;}
case 'download-export':{const output=M.resolveExport(model,b.dataset.entitlement||model.correction.exports.at(-1)?.entitlement.entitlementId,'fixture-owner-01',b.dataset.kind||'artwork_export');const blob=new Blob([output.content],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);download(url,output.versionId+'-illustrative.svg');setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
case 'renew-export':model.exportState='entitled';persistRender('Simulated download access renewed; owned entitlement preserved.');break;
case 'account-signin':model.identity='simulated';persistRender('Simulated owner account.');break;
case 'publish':run('publish',{consent:$('#gallery-consent').checked});break;
case 'gallery-like':model.galleryLiked=!model.galleryLiked;persistRender(model.galleryLiked?'Showcase liked in this local review.':'Local showcase like removed.');break;
case 'gallery-share':openDialog('Share showcase review link',`<p>Local review URL; no public original access.</p><input aria-label="Showcase review URL" readonly value="${e(location.href)}">`);break;
case 'gallery-report':openDialog('Report showcase concern',`${field('Concern','gallery-concern','','textarea')}${mb('Submit local moderation report','gallery-report-submit')}`);break;
case 'gallery-report-submit':if(!$('#gallery-concern').value.trim())announce('Describe the concern.');else{model.galleryReports.push($('#gallery-concern').value.trim());$('#dialog').close();save();announce('Local moderation report recorded for this review.');}break;
case 'side':model.scene.side=b.dataset.side;persistRender();break;
case 'panel':model.scene.panel=b.dataset.panel;persistRender();break;
case 'select-layer':model.scene.selected=b.dataset.layer;save();if(!b.classList.contains('scene-layer'))render();break;
case 'add-image':case 'add-text':case 'up':case 'down':case 'visible':case 'lock':case 'remove':case 'undo':case 'redo':M.sceneEdit(model,a);model.scene.panel='controls';persistRender('Composition updated.');break;
case 'apply-layer':{const p={};for(const k of ['xMm','yMm','widthMm','heightMm','rotation']){p[k]=Number($('#layer-'+k).value);if(!Number.isFinite(p[k])||['widthMm','heightMm'].includes(k)&&p[k]<=0)throw Error('Use finite coordinates and positive sizes.');}if($('#layer-text'))p.text=$('#layer-text').value;M.sceneEdit(model,'update',p);persistRender('Physical geometry saved in millimeters.');break;}
case 'original-download':{const l=model.scene[model.scene.side].find(x=>x.id===model.scene.selected);if(l?.source.startsWith('data:'))download(l.source,'unchanged-original.'+(l.source.startsWith('data:image/jpeg')?'jpg':l.source.startsWith('data:image/webp')?'webp':'png'));break;}
case 'save-scene':save();announce('Local draft saved for this tab. No account or server persistence.');break;
case 'composition-quote':M.compositionQuote(model,$('#composition-size').value);persistRender('Simulated quote bound to frozen proof. Production checkout remains unavailable.');break;
case 'composition-export':openDialog('Composed artwork export',`<p>Exact frozen composition ${e(model.correction.reviewVersion)}. Separate entitlement for front and back composed artwork; no garment photograph or manufacturing master.</p>${check('I consent to the separate illustrative export.','composition-export-consent')}${mb('Simulate composition export entitlement','composition-export-authorize')}`);break;
case 'composition-export-authorize':if(!$('#composition-export-consent').checked)throw Error('Explicit consent required.');M.purchaseExport(model,'composition_export',model.correction.reviewVersion);$('#dialog').close();save();go('/account/exports');break;
case 'freeze':M.freeze(model);save();go('/customize/composition-01/review');break;
case 'add-frozen':{M.addFrozen(model,$('#composition-size').value);save();go('/cart');break;}
case 'cart-remove':{const removed=model.cart.splice(Number(b.dataset.index),1)[0];model.correction.cartBindings=model.correction.cartBindings.filter(l=>l.compositionVersionId!==removed.versionId);}persistRender('Removed from simulated cart.');break;
case 'cart-quote':{const c=model.cart[Number(b.dataset.index)];openDialog('Personalization quote unavailable',`<p>Frozen ${e(c.versionId)} / ${e(c.quote)}.</p><p>${c.quote==='expired'?'Expired quote requires a new validated composition quote and fresh consent.':''} Supplier print zones, final price and regional shipping are unapproved. Checkout remains disabled; no substitute price is invented.</p>`);break;}
}}catch(x){error=x.message;render();announce(x.message);}});
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click();}
function legacyClick(ev,b){const a=b.dataset.action;if(a==='close-dialog'){$('#dialog').close();return;}if(a==='upload-entry'){ev.preventDefault();model.scene.provenance='byo';save();go('/customize');return;}if(a==='filter'){S.filter=b.dataset.filter;render();}if(a==='size'){S.size=b.dataset.size;S.error='';render();}if(a==='size-guide')openDialog('Fit information pending','<p>Garment-specific measurements and supplier size range remain unconfirmed.</p>');if(a==='product-view'){S.productView=b.dataset.view;render();}if(a==='zoom-product')openDialog('Illustrative garment',photo(S.product,S.productView));if(a==='add-bag'){if(!S.size){S.error='Choose a demo size to continue.';render();return;}model.cart.push({versionId:'collection-'+S.product,size:S.size,region:model.region,quote:'valid',front:[],back:[]});save();go('/cart');}if(a==='customize'){model.scene.provenance='byo';M.sceneEdit(model,'add-image',{source:M.artFiles[S.product==='chromatic'?1:0]});save();go('/customize');}}
document.addEventListener('keydown',ev=>{const t=ev.target;if(t.matches('[data-layer].scene-layer')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key)){ev.preventDefault();model.scene.selected=t.dataset.layer;const l=model.scene[model.scene.side].find(l=>l.id===t.dataset.layer),n=ev.shiftKey?5:1;if(l.locked){announce('Layer locked. Unlock in Controls.');return;}M.sceneEdit(model,'update',{xMm:l.xMm+(ev.key==='ArrowRight'?n:ev.key==='ArrowLeft'?-n:0),yMm:l.yMm+(ev.key==='ArrowDown'?n:ev.key==='ArrowUp'?-n:0)});save();render();document.querySelector(`[data-layer="${l.id}"].scene-layer`)?.focus();}});
let drag=null;
document.addEventListener('pointerdown',ev=>{const t=ev.target.closest('.scene-layer');if(!t)return;const l=model.scene[model.scene.side].find(l=>l.id===t.dataset.layer);if(l.locked)return;model.scene.selected=l.id;drag={id:l.id,x:ev.clientX,y:ev.clientY,initialX:l.xMm,initialY:l.yMm,rect:t.parentElement.getBoundingClientRect(),before:M.sceneSnapshot(model.scene)};t.setPointerCapture(ev.pointerId);});
document.addEventListener('pointermove',ev=>{if(!drag)return;const l=model.scene[model.scene.side].find(l=>l.id===drag.id);l.xMm=Math.round(drag.initialX+(ev.clientX-drag.x)/drag.rect.width*200);l.yMm=Math.round(drag.initialY+(ev.clientY-drag.y)/drag.rect.height*260);const t=document.querySelector(`[data-layer="${l.id}"].scene-layer`);t.style.left=l.xMm/2+'%';t.style.top=l.yMm/2.6+'%';});
document.addEventListener('pointerup',()=>{if(!drag)return;model.scene.undo.push(drag.before);model.scene.redo=[];model.scene.revision++;drag=null;persistRender('Placement updated in millimeters.');});document.addEventListener('pointercancel',()=>{if(drag){model.scene.front=drag.before.front;model.scene.back=drag.before.back;drag=null;render();}});
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();error='';message='';render(true);});
if(scenario&&!location.hash)location.hash=M.scenarioRoute(scenario,model);
render();
// Deliberately explicit review-only interface for automated QA. Never grants real authority.
window.AtelierReview={get model(){return structuredClone(model);},load(name){model=M.fixture(name);save();go(M.scenarioRoute(name,model));render(true);},reset(){model=M.initial();save();go('/studio');},project(){return M.screen(model);}};
